class NumberCollection {
  private items: number[] = [];
  add(n: number) { this.items.push(n); }
  createIterator() {
    let index = 0;
    return { next: () => ({ value: this.items[index++], done: index > this.items.length }) };
  }
}

class Menu {
  private items: MenuItem[] = [];
  add(item: MenuItem) { this.items.push(item); }
  getItems(): MenuItem[] { return this.items; }
}

